def transform(grid):
    """Connect successive occurrences of the non-background marker color."""
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    markers = [value for value in counts if value != background and value != 2]
    marker = max(markers, key=lambda value: counts[value])
    out = [row[:] for row in grid]

    for r in range(h):
        positions = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2

    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
